export function initCheckboxes() {
  const checkboxes = document.querySelectorAll('[data-module="nhsuk-checkboxes"]');
  checkboxes.forEach(container => {
    const inputs = container.querySelectorAll('input[type="checkbox"]');
    inputs.forEach(input => {
      input.addEventListener('click', handleClick);
      input.addEventListener('change', handleChange);
    });
  });

  function handleClick(event) {
    const input = event.target;
    if (input.hasAttribute('data-checkbox-exclusive')) {
      const group = input.getAttribute('data-checkbox-exclusive-group');
      if (group && input.checked) {
        container.querySelectorAll(`input[type="checkbox"][data-checkbox-exclusive-group="${group}"]:not([data-checkbox-exclusive])`).forEach(cb => {
          cb.checked = false;
          cb.dispatchEvent(new Event('change', { bubbles: true }));
        });
      }
    }
  }

  function handleChange(event) {
    const input = event.target;
    if (input.matches('input[type="checkbox"][data-checkbox-exclusive]')) {
      const group = input.getAttribute('data-checkbox-exclusive-group');
      if (group && input.checked) {
        document.querySelectorAll(`input[type="checkbox"][data-checkbox-exclusive-group="${group}"]:not([data-checkbox-exclusive])`).forEach(cb => {
          cb.checked = false;
          cb.dispatchEvent(new Event('change', { bubbles: true }));
        });
      }
    }
  }
}
